insert into public.organizations(id,name,region) values ('10000000-0000-4000-8000-000000000001','Estancia Didáctica Concordia','Concordia, Entre Ríos (ficticio)'),('10000000-0000-4000-8000-000000000002','Estancia Aislada','Entre Ríos (ficticio)') on conflict do nothing;
insert into public.plots(id,organization_id,name,crop,geom)
insert into public.stations(id,plot_id,name,lat,lng) select ('30000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Estación '||n,-31.397,-58.037+n*0.008 from generate_series(1,4) n on conflict do nothing;
insert into public.valves(id,plot_id,name) select ('40000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Válvula '||n from generate_series(1,4) n on conflict do nothing;
insert into public.readings(station_id,measured_at,moisture_pct,temp_c,rain_mm,source) select ('30000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now()-i*interval '10 minutes',case n when 1 then 35 when 2 then 18 else 30 end + sin(i)*2,24+cos(i),0,'sensor' from generate_series(1,4) n cross join generate_series(0,42) i where n<>3 or i>=2 on conflict do nothing;
